    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    for r in range(1,h-1):
        for c in range(1,w-1):
            cells=[(r,c),(r-1,c),(r+1,c),(r,c-1),(r,c+1)]
            if all(grid[y][x]==4 for y,x in cells):
                for y,x in cells:g[y][x]=8
    return g
